## JavaScript

```javascript
/**
 * Returns the smaller of two numbers.
 * @param {number} a
 * @param {number} b
 * @returns {number}
 */
function minOfTwo(a, b) {
    return (a < b) ? a : b;
}

// Example usage
console.log(minOfTwo(10, 5));   // 5
console.log(minOfTwo(-3, 7));   // -3
```

